<?php
$root=getenv('GRW_WP_ROOT');require $root.'/wp-load.php';
use Webifya\GRW\{Locations,Reviews,Widgets,Renderer,Cache,Analytics};
global $wpdb;$location=Locations::save(['name'=>'Synthetic benchmark fixtures','provider'=>'import','active'=>true]);$widget=Widgets::save(['name'=>'Benchmark 100 visible','config'=>['source'=>'','locations'=>[$location],'limit'=>100]]);$previous=0;$results=[];$savedSettings=get_option('grw_settings');update_option('grw_settings',array_merge($savedSettings,['analytics'=>true,'consent_required'=>true]));wp_set_current_user(0);
foreach([10,100,1000,10000] as $n){$start=microtime(true);for($offset=$previous;$offset<$n;$offset+=500){$batch=[];for($i=$offset;$i<min($offset+500,$n);$i++)$batch[]=['external_id'=>'benchmark-'.$i,'reviewer'=>'Sample benchmark '.$i,'rating'=>5,'content'=>'Synthetic performance fixture, not a real customer review. বাংলা العربية.','review_date'=>'2024-01-01','source_name'=>'Synthetic benchmark'];$batchStart=microtime(true);$r=Reviews::import($batch,$location);$batchMs=(microtime(true)-$batchStart)*1000;if($r['errors'])throw new RuntimeException('Fixture import failed');}$import=(microtime(true)-$start)*1000;$previous=$n;
Cache::invalidate();$q=$wpdb->num_queries;$start=microtime(true);$rows=Reviews::query(['locations'=>[$location]],1,100);$cold=(microtime(true)-$start)*1000;$coldq=$wpdb->num_queries-$q;$q=$wpdb->num_queries;$start=microtime(true);Reviews::query(['locations'=>[$location]],1,100);$warm=(microtime(true)-$start)*1000;$warmq=$wpdb->num_queries-$q;$start=microtime(true);$html=Renderer::render($widget); if (substr_count($html,'<article')!==min(100,$n)) { throw new RuntimeException('Benchmark must render actual fixture cards'); }$render=(microtime(true)-$start)*1000;$start=microtime(true);Reviews::query(['locations'=>[$location],'admin'=>true],1,50);$admin=(microtime(true)-$start)*1000;
$event=new WP_REST_Request('POST');$event->set_param('session',md5(wp_generate_uuid4()));$event->set_param('consent',true);$event->set_param('events',[['widget'=>$widget,'event'=>'impression'],['widget'=>$widget,'event'=>'next'],['widget'=>$widget,'event'=>'readmore']]);$analyticsStart=microtime(true);$accepted=Analytics::collect($event);if(is_wp_error($accepted)||$accepted['accepted']!==3)throw new RuntimeException('Benchmark analytics must perform real fixture writes');$analyticsMs=(microtime(true)-$analyticsStart)*1000;
$results[]=['stored' =>$n,'last_import_batch_rows'=>count($batch),'last_import_batch_ms'=>round($batchMs,2),'analytics_three_events_ms'=>round($analyticsMs,2),'database_server_memory_bytes'=>null,'new_fixture_import_ms'=>round($import,2),'cold_query_ms'=>round($cold,2),'cold_queries'=>$coldq,'cached_query_ms'=>round($warm,2),'cached_queries'=>$warmq,'render_100_ms'=>round($render,2),'admin_50_ms'=>round($admin,2),'html_bytes'=>strlen($html),'peak_memory_bytes'=>memory_get_peak_usage(true)];}
echo wp_json_encode(['environment'=>['wordpress'=>get_bloginfo('version'),'php'=>PHP_VERSION,'database'=>defined('DB_ENGINE')&&DB_ENGINE==='sqlite'?'SQLite via official WordPress integration (MySQL compatibility API)':$wpdb->db_version(),'os'=>PHP_OS,'display_limit'=>100,'runs_per_measurement'=>1],'results'=>$results],JSON_PRETTY_PRINT)."\n";
$wpdb->delete($wpdb->prefix.'grw_reviews',['location_id'=>$location]);$wpdb->delete($wpdb->prefix.'grw_locations',['id'=>$location]);$wpdb->delete($wpdb->prefix.'grw_widgets',['id'=>$widget]);$wpdb->delete($wpdb->prefix.'grw_analytics',['widget_id'=>$widget]);update_option('grw_settings',$savedSettings);Cache::invalidate();
